layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(242, 245, 247); border-radius: 4.5px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 18px; padding-right: 18px; padding-bottom: 18px; padding-left: 18px; transition: all; position: relative }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #2ea24a; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(52, 199, 89); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 36px; font-weight: 500; font-style: normal; line-height: 1.35; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 500; font-style: normal; line-height: 1.35; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="pitch"]::before { content: ""; display: block; position: absolute; height: 145.375px; color: var(--ryt-text); background-color: rgb(52, 199, 89); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 2px; padding-right: 2px; padding-bottom: 2px; padding-left: 2px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
